def expand(nodes, bg, line):
    m,n=len(nodes),len(nodes[0]); g=[[bg]*(2*n-1) for _ in range(2*m-1)]
    for i in range(2*m-1):
        if i%2==0:
            for j in range(2*n-1):
                if j%2==0:g[i][j]=line
        else:
            for j in range(2*n-1):
                if j%2==0:g[i][j]=line
    for i in range(m):
        for j in range(n):g[2*i][2*j]=nodes[i][j]
    return g

